import type { MultiSelectChipCloseButtonProps } from "../multi-select.types";

import React from "react";
import { Chip } from "@components/chip";

import { useMultiSelect } from "../hooks/use-multi-select";

export const MultiSelectChipCloseButton: React.FC<MultiSelectChipCloseButtonProps> = ({
  value,
  onClick,
  ...props
}) => {
  const { onSingleValueChange, triggerRef, disabled } = useMultiSelect();

  const handleClose = (e: React.MouseEvent<HTMLSpanElement>) => {
    e.stopPropagation();
    onSingleValueChange(value);
    onClick?.(e);
    triggerRef.current?.focus();
  };

  return (
    <Chip.CloseButton
      {...props}
      aria-disabled={disabled}
      tabIndex={disabled ? -1 : 0}
      onClick={handleClose}
      onPointerDown={(e) => e.preventDefault()}
    />
  );
};
MultiSelectChipCloseButton.displayName = "MultiSelect.ChipCloseButton";
